import Foundation

/// 사회 개념 사전 보충: 중학교 사회①·②, 역사 (2015·2022 개정)
extension DoitCurriculum {
    static let socialMiddleMore: [CurriculumEntry] = [
        // 사회①
        ce(.middle, "지구 곳곳에서 일어나는 자연재해", ["자연재해", "기후적 재해", "지형적 재해"], "자연재해는 자연 현상 때문에 사람의 생명과 재산이 피해를 입는 거예요. 홍수, 가뭄, 열대 저기압, 폭설 같은 기후적 자연재해와 지진, 화산 활동, 지진 해일 같은 지형적 자연재해가 있어요.\n예: 우리나라에서는 여름철 집중 호우와 태풍 피해가 자주 일어나요."),
        ce(.middle, "지구 곳곳에서 일어나는 자연재해", ["열대 저기압", "허리케인", "사이클론"], "열대 저기압은 열대 바다에서 발생해 강한 바람과 많은 비를 동반하는 저기압이에요. 발생 지역에 따라 북서태평양에서는 태풍, 북대서양과 북동태평양에서는 허리케인, 인도양과 남태평양에서는 사이클론이라고 불러요.\n예: 태풍은 주로 여름에서 초가을에 우리나라에 영향을 줘요."),
        ce(.middle, "지구 곳곳에서 일어나는 자연재해", ["홍수와 가뭄", "홍수", "가뭄"], "홍수는 많은 비가 짧은 기간에 내려 하천이 넘치거나 낮은 땅이 물에 잠기는 현상이고, 가뭄은 오랫동안 비가 내리지 않아 물이 부족한 현상이에요. 홍수는 댐과 제방, 가뭄은 저수지와 지하수 개발 등으로 대비해요.\n예: 아프리카의 사헬 지대는 가뭄과 사막화 피해가 큰 지역이에요."),
        ce(.middle, "지구 곳곳에서 일어나는 자연재해", ["지진과 화산 피해", "지진 해일", "쓰나미"], "지진과 화산 활동은 주로 판의 경계에서 일어나요. 지진은 건물 붕괴와 화재를 일으키고, 바다 밑에서 지진이 일어나면 거대한 지진 해일(쓰나미)이 해안을 덮쳐요. 화산 폭발은 용암과 화산재로 피해를 주지만, 화산 주변은 비옥한 토양과 관광·지열 자원으로 이용되기도 해요.\n예: 2011년 동일본 대지진 때 지진 해일로 큰 피해가 났어요."),
        ce(.middle, "정치 생활과 민주주의", ["정치의 의미", "넓은 의미의 정치", "좁은 의미의 정치"], "좁은 의미의 정치는 국가 권력을 얻고 유지하고 행사하는 활동이고, 넓은 의미의 정치는 사회 구성원 사이의 이해관계와 갈등을 조정하고 해결하는 모든 활동이에요.\n예: 학급 회의에서 체험 학습 장소를 정하는 것은 넓은 의미의 정치예요."),
        ce(.middle, "정치 생활과 민주주의", ["민주 정치의 발전", "근대 민주 정치", "현대 민주 정치"], "고대 아테네에서는 시민이 민회에 직접 참여하는 직접 민주 정치가 이루어졌지만 여성, 노예, 외국인은 참여할 수 없었어요. 근대에는 시민 혁명을 거쳐 국민 주권과 기본권 보장이 확립되었고, 현대에는 보통 선거가 확대되어 모든 국민이 정치에 참여하는 대중 민주주의가 이루어졌어요.\n예: 영국의 명예혁명, 미국 독립 혁명, 프랑스 혁명은 대표적인 시민 혁명이에요."),
        ce(.middle, "정치 생활과 민주주의", ["민주주의의 기본 원리", "국민 주권", "입헌주의"], "민주 정치는 국가의 주인이 국민이라는 국민 주권의 원리, 국민이 스스로 다스리는 국민 자치의 원리, 헌법에 따라 국가 권력을 행사하는 입헌주의의 원리, 권력을 나누어 서로 견제하게 하는 권력 분립의 원리를 바탕으로 해요. 그 근본 이념은 인간의 존엄성 실현이에요.\n예: 대한민국 헌법 제1조 2항 '대한민국의 주권은 국민에게 있고, 모든 권력은 국민으로부터 나온다'는 국민 주권의 원리를 나타내요."),
        ce(.middle, "정치 생활과 민주주의", ["정부 형태", "대통령제와 의원 내각제의 비교"], "정부 형태는 입법부와 행정부의 관계에 따라 대통령제와 의원 내각제로 나뉘어요. 대통령제는 국민이 선출한 대통령이 행정부를 이끌며 입법부와 엄격히 분리되고, 의원 내각제는 의회의 다수당이 내각을 구성하여 입법부와 행정부가 긴밀히 협조해요.\n예: 미국은 대통령제, 영국은 의원 내각제를 대표하는 나라예요."),
        ce(.middle, "정치 생활과 민주주의", ["선거와 선거 제도", "선거 관리 위원회", "선거 공영제", "게리맨더링"], "선거는 국민의 대표를 뽑는 민주 정치의 핵심 제도로, 보통·평등·직접·비밀 선거의 원칙에 따라 치러져요. 공정한 선거를 위해 독립된 헌법 기관인 선거 관리 위원회를 두고, 선거 비용의 일부를 국가가 부담하는 선거 공영제를 시행하며, 선거구를 법률로 정하는 선거구 법정주의를 따라요.\n예: 특정 정당에 유리하게 선거구를 정하는 것을 게리맨더링이라고 해요."),
        ce(.middle, "일상생활과 법", ["사회 규범", "법과 도덕"], "사회 규범은 사회 구성원이 지켜야 할 행동 기준으로 관습, 도덕, 종교 규범, 법 등이 있어요. 도덕은 양심에 따라 스스로 지키는 것이지만, 법은 국가 권력에 의해 강제되며 어기면 처벌이나 제재를 받는다는 점이 달라요.\n예: 웃어른께 인사하는 것은 도덕, 교통 신호를 지키는 것은 법이 정한 규범이에요."),
        ce(.middle, "일상생활과 법", ["법의 목적", "정의의 실현", "공공복리"], "법은 사회 구성원의 자유와 권리를 보장하고 사회 질서를 유지하기 위해 존재해요. 법이 추구하는 목적으로는 각자에게 정당한 몫을 주는 정의의 실현, 사회 구성원 전체의 이익인 공공복리의 증진 등이 있어요.\n예: 장애인 편의 시설 설치를 의무로 정한 법은 정의와 공공복리를 함께 추구해요."),
        ce(.middle, "일상생활과 법", ["민사 분쟁의 해결", "손해 배상"], "개인 간에 재산이나 가족 관계 등으로 생긴 다툼을 민사 분쟁이라고 해요. 당사자 간 협상이나 조정으로 해결하기 어려우면 민사 재판을 통해 해결해요. 고의나 실수로 다른 사람에게 손해를 입히면 손해 배상 책임을 져요.\n예: 이웃집 유리창을 깨뜨렸다면 유리창 값을 물어 줘야 해요."),
        ce(.middle, "일상생활과 법", ["청소년 근로자의 권리", "청소년의 근로"], "청소년도 일할 때 근로 기준법으로 보호받아요. 원칙적으로 만 15세 이상이면 일할 수 있고, 근로 계약서를 써야 하며, 최저 임금 이상을 받아야 해요. 만 18세 미만은 부모님 동의서와 가족 관계 증명서가 필요하고, 유해하거나 위험한 일은 할 수 없어요.\n예: 만 18세 미만 청소년의 근로 시간은 하루 7시간, 1주 35시간을 넘을 수 없어요."),

        // 사회②
        ce(.middle, "헌법과 국가 기관", ["국회", "입법부", "국회의 권한"], "국회는 국민의 대표인 국회의원으로 구성된 입법 기관이에요. 법률을 만들거나 고치는 입법에 관한 일, 예산안을 심의·확정하는 재정에 관한 일, 국정 감사와 국정 조사 등으로 정부를 견제하는 일을 해요. 국회의원의 임기는 4년이에요.\n예: 국회는 대통령이 국무총리를 임명할 때 동의할지를 결정해요."),
        ce(.middle, "헌법과 국가 기관", ["대통령과 행정부", "대통령의 권한", "국무총리와 국무 회의"], "행정부는 법을 집행하여 국가 정책을 실현하는 기관이고, 대통령은 행정부의 수반이자 국가 원수예요. 대통령의 임기는 5년이고 중임할 수 없어요. 국무총리는 대통령을 보좌하고 행정 각부를 통할하며, 국무 회의는 정부의 중요 정책을 심의해요.\n예: 대통령은 국군 통수권, 조약 체결권, 공무원 임명권 등을 가져요."),
        ce(.middle, "헌법과 국가 기관", ["법원", "사법부", "심급 제도", "3심제"], "법원은 법에 따라 재판을 하는 사법 기관이에요. 공정한 재판을 위해 사법권의 독립이 보장되고, 한 사건에 대해 원칙적으로 세 번까지 재판을 받을 수 있는 심급 제도를 두고 있어요. 대법원은 최고 법원으로, 명령·규칙·처분이 헌법이나 법률에 위반되는지 최종적으로 심사해요.\n예: 1심 판결에 불복하면 항소하고, 2심 판결에 불복하면 대법원에 상고할 수 있어요."),
        ce(.middle, "헌법과 국가 기관", ["헌법 재판소의 역할", "헌법재판소", "위헌 법률 심판", "헌법 소원 심판"], "헌법 재판소는 헌법을 수호하고 국민의 기본권을 보장하기 위한 기관이에요. 법률이 헌법에 위반되는지 판단하는 위헌 법률 심판, 공권력에 의해 기본권을 침해당한 국민이 청구하는 헌법 소원 심판, 탄핵 심판, 정당 해산 심판, 권한 쟁의 심판을 맡아요.\n예: 헌법 재판소는 9명의 재판관으로 구성돼요."),
        ce(.middle, "헌법과 국가 기관", ["권력 분립", "견제와 균형"], "권력 분립은 국가 권력을 입법권, 행정권, 사법권으로 나누어 서로 다른 기관이 맡게 하는 원리예요. 한 기관이 권력을 독점하면 국민의 자유와 권리가 침해될 수 있으므로, 세 기관이 서로 견제하고 균형을 이루게 해요.\n예: 국회는 법률을 만들고, 대통령은 법률안 거부권을 가지며, 법원은 법률의 위헌 여부 심판을 헌법 재판소에 제청할 수 있어요."),
        ce(.middle, "경제생활과 선택", ["경제 활동", "생산, 분배, 소비", "재화와 서비스"], "경제 활동은 사람들이 생활에 필요한 재화와 서비스를 생산하고, 분배하고, 소비하는 모든 활동이에요. 재화는 옷이나 음식처럼 형태가 있는 것이고, 서비스는 의사의 진료나 가수의 공연처럼 사람의 행위예요.\n예: 공장에서 빵을 만드는 것은 생산, 일한 대가로 월급을 받는 것은 분배, 빵을 사 먹는 것은 소비예요."),
        ce(.middle, "경제생활과 선택", ["경제 주체", "가계, 기업, 정부"], "경제 활동을 하는 주체에는 가계, 기업, 정부가 있어요. 가계는 생산 요소를 제공하고 소득으로 소비하는 소비 주체, 기업은 재화와 서비스를 생산하는 생산 주체, 정부는 세금을 걷어 공공재를 공급하고 경제 활동을 조정하는 주체예요.\n예: 정부는 세금으로 도로와 학교 같은 공공재를 만들어요."),
        ce(.middle, "경제생활과 선택", ["기업의 사회적 책임", "기업가 정신"], "기업은 이윤을 추구하지만, 법을 지키고 소비자와 근로자의 권리를 존중하며 환경 보호와 사회 공헌에 힘써야 하는 사회적 책임이 있어요. 새로운 기술과 아이디어로 위험을 무릅쓰고 혁신하는 자세를 기업가 정신이라고 해요.\n예: 친환경 제품을 개발하거나 이익의 일부를 지역 사회에 기부하는 것은 기업의 사회적 책임을 실천하는 거예요."),
        ce(.middle, "경제생활과 선택", ["자산 관리", "금융 상품", "안전성, 수익성, 유동성"], "자산 관리는 생애 동안 안정적인 경제생활을 위해 자산을 계획적으로 모으고 운용하는 거예요. 금융 상품은 원금을 잃지 않을 안전성, 이익을 얻을 수익성, 필요할 때 현금으로 바꿀 수 있는 유동성을 고려해 골라요. 예금은 안전성이 높고, 주식은 수익성이 높을 수 있지만 위험도 커요.\n예: 여러 금융 상품에 나누어 투자하는 분산 투자는 위험을 줄이는 방법이에요."),
        ce(.middle, "경제생활과 선택", ["신용", "신용 관리"], "신용은 나중에 갚겠다는 약속을 믿고 돈이나 물건을 먼저 빌리는 거예요. 신용 카드나 대출을 쓰고 제때 갚지 않으면 신용 점수가 낮아져 금융 거래에 불이익을 받을 수 있으므로 소득에 맞게 계획적으로 써야 해요.\n예: 신용 카드는 지금 결제하지만 돈은 나중에 갚는 외상 구매예요."),
        ce(.middle, "국민 경제와 국제 거래", ["국내 총생산의 의미", "GDP", "1인당 국내 총생산"], "국내 총생산(GDP)은 일정 기간 동안 한 나라 안에서 새로 생산된 최종 생산물의 시장 가치를 모두 합한 거예요. 국적에 관계없이 국내에서 생산된 것만 포함하고, 중간재나 시장에서 거래되지 않는 가사 노동 등은 포함하지 않아요. 1인당 국내 총생산은 국민의 평균적인 생활 수준을 짐작하게 해요.\n예: 외국 기업이 우리나라에 세운 공장의 생산물은 우리나라 GDP에 포함돼요."),
        ce(.middle, "국민 경제와 국제 거래", ["경제 성장", "경제 성장률"], "경제 성장은 한 나라의 경제 규모가 커지는 것으로, 보통 실질 국내 총생산의 증가율인 경제 성장률로 나타내요. 경제가 성장하면 일자리와 소득이 늘고 생활 수준이 높아지지만, 환경 오염이나 빈부 격차 같은 문제가 생기기도 해요.\n예: 올해 실질 GDP가 작년보다 3% 늘었다면 경제 성장률은 3%예요."),
        ce(.middle, "국민 경제와 국제 거래", ["물가와 인플레이션의 영향", "물가 지수"], "물가는 여러 상품의 가격을 종합하여 평균적으로 나타낸 것으로 물가 지수로 측정해요. 물가가 계속 오르면 화폐 가치가 떨어져 같은 돈으로 살 수 있는 물건이 줄어들고, 봉급 생활자와 예금자는 불리해지며 실물 자산 보유자는 유리해져요.\n예: 물가가 2배로 오르면 같은 1만 원으로 살 수 있는 물건의 양이 절반으로 줄어요."),
        ce(.middle, "국민 경제와 국제 거래", ["실업의 종류", "마찰적 실업", "구조적 실업", "경기적 실업"], "실업은 일할 능력과 의사가 있는데도 일자리를 얻지 못한 상태예요. 더 나은 일자리를 찾는 과정에서 생기는 마찰적 실업, 산업 구조 변화나 기술 발달로 생기는 구조적 실업, 경기가 나빠져 생기는 경기적 실업, 계절에 따라 생기는 계절적 실업이 있어요.\n예: 스마트폰 보급으로 필름 카메라 공장이 문을 닫아 생긴 실업은 구조적 실업이에요."),
        ce(.middle, "국민 경제와 국제 거래", ["국제 거래와 환율 변동", "환율 상승의 영향"], "국제 거래는 나라 사이에 재화, 서비스, 생산 요소 등을 사고파는 거예요. 외국 돈과 우리 돈의 교환 비율을 환율이라고 하는데, 환율이 오르면(원화 가치 하락) 수출품의 외화 표시 가격이 낮아져 수출이 늘고, 수입품 가격이 올라 수입은 줄어들어요.\n예: 1달러에 1000원이던 환율이 1200원이 되면 미국 여행 비용이 원화로 더 많이 들어요."),
        ce(.middle, "국제 사회와 국제 정치", ["국제 사회의 특성", "주권 국가"], "국제 사회는 여러 주권 국가가 서로 관계를 맺으며 이루어진 사회예요. 각 국가는 자국의 이익을 우선 추구하고, 국가 사이의 문제를 강제로 해결할 중앙 정부가 없어 힘의 논리가 작용하기도 해요. 하지만 국제법과 국제기구를 통해 협력하려는 노력도 커지고 있어요.\n예: 기후 변화 문제를 해결하려고 여러 나라가 국제 협약을 맺어요."),
        ce(.middle, "국제 사회와 국제 정치", ["국제 사회의 행위 주체", "정부 간 국제기구", "국제 비정부 기구"], "국제 사회의 행위 주체에는 국가, 국제 연합(UN) 같은 정부 간 국제기구, 그린피스·국경 없는 의사회 같은 국제 비정부 기구, 다국적 기업, 영향력 있는 개인 등이 있어요. 가장 기본적인 행위 주체는 국가예요.\n예: 전직 국가 원수나 노벨 평화상 수상자 같은 개인도 국제 분쟁 해결에 영향을 미쳐요."),
        ce(.middle, "국제 사회와 국제 정치", ["외교", "공공 외교"], "외교는 국가가 평화적인 방법으로 다른 나라와 관계를 맺고 자국의 이익을 추구하는 활동이에요. 정부뿐 아니라 민간단체와 개인도 문화 교류 등으로 다른 나라 국민에게 직접 다가가는 공공 외교에 참여할 수 있어요.\n예: 한류 문화 콘텐츠는 다른 나라 사람들이 우리나라를 긍정적으로 보게 하는 데 도움을 줘요."),
        ce(.middle, "국제 사회와 국제 정치", ["우리나라와 주변국의 갈등", "동북공정", "역사 왜곡"], "우리나라는 주변국과 역사 문제와 영토 문제로 갈등을 겪고 있어요. 일본은 독도에 대한 부당한 영유권 주장, 역사 교과서 왜곡, 일본군 '위안부' 문제의 책임 회피 등으로, 중국은 고구려와 발해의 역사를 중국 역사로 편입하려는 동북공정으로 갈등을 일으켰어요.\n예: 독도는 역사적·지리적·국제법적으로 명백한 우리 영토예요."),
        ce(.middle, "사람이 만든 삶터, 도시", ["도시의 특징", "도시의 기능"], "도시는 많은 인구가 좁은 지역에 모여 살고, 주민 대부분이 2·3차 산업에 종사하는 곳이에요. 행정, 상업, 교육, 문화 등의 기능이 모여 있어 주변 지역의 중심지 역할을 해요.\n예: 서울은 정치·경제·문화의 중심지로 많은 기능이 모여 있어요."),
        ce(.middle, "사람이 만든 삶터, 도시", ["도시 내부 구조", "도심", "부도심"], "도시가 커지면 기능이 지역별로 나뉘는 지역 분화가 일어나요. 도심은 접근성과 땅값이 높아 중심 업무 기능과 고급 상점이 모이고, 부도심은 도심의 기능을 나누어 맡으며, 주변 지역에는 주택과 학교, 공장이 들어서요.\n예: 도심에는 고층 빌딩이 많고 땅값이 비싸요."),
        ce(.middle, "사람이 만든 삶터, 도시", ["인구 공동화 현상", "도심의 인구 공동화"], "도심은 땅값이 비싸 주거 기능이 빠져나가므로 낮에는 사람이 많지만 밤에는 인구가 적어지는데, 이것을 인구 공동화 현상이라고 해요. 이 때문에 도심은 상주인구가 적고 주간 인구가 많아요.\n예: 서울의 도심은 밤보다 낮에 사람이 훨씬 많아요."),
        ce(.middle, "사람이 만든 삶터, 도시", ["살기 좋은 도시", "도시 재생"], "살기 좋은 도시는 깨끗한 자연환경, 편리한 교통과 생활 시설, 안정된 일자리, 안전, 다양한 문화를 갖춘 도시예요. 도시 문제를 해결하기 위해 대중교통을 늘리고, 녹지를 확보하며, 오래된 지역을 정비하는 도시 재생 사업을 해요.\n예: 브라질 쿠리치바는 버스 중심의 대중교통 체계로 교통 문제를 줄인 도시로 유명해요."),
        ce(.middle, "환경 문제와 지속 가능한 환경", ["전 지구적 환경 문제", "사막화", "열대림 파괴"], "환경 문제는 오염 물질이 바람과 해류를 따라 국경을 넘어 이동하므로 여러 나라가 함께 해결해야 해요. 대표적인 전 지구적 환경 문제로 지구 온난화, 사막화, 열대림 파괴, 해양 쓰레기 문제 등이 있어요.\n예: 아마존 열대림이 파괴되면 흡수되는 이산화 탄소가 줄어 지구 온난화가 심해져요."),
        ce(.middle, "환경 문제와 지속 가능한 환경", ["환경 문제 유발 산업의 이전", "공해 유발 산업", "전자 쓰레기"], "선진국은 환경 규제가 엄격해서 오염 물질을 많이 배출하는 산업이나 전자 쓰레기를 환경 규제가 약한 개발 도상국으로 옮기기도 해요. 이 때문에 개발 도상국은 일자리와 소득을 얻지만 심각한 환경 오염과 주민의 건강 피해를 겪어요.\n예: 선진국에서 버린 전자 쓰레기가 아프리카와 아시아의 일부 나라로 옮겨져 처리되고 있어요."),
        ce(.middle, "환경 문제와 지속 가능한 환경", ["생활 속 환경 이슈", "로컬 푸드", "유전자 변형 식품"], "우리 생활과 관련된 환경 이슈에는 미세 먼지, 플라스틱 쓰레기, 유전자 변형 식품(GMO), 로컬 푸드 등이 있어요. 로컬 푸드는 가까운 지역에서 생산된 먹을거리로, 운송 거리가 짧아 신선하고 운송 과정의 탄소 배출을 줄여요.\n예: 장바구니와 텀블러를 쓰면 일회용 쓰레기를 줄일 수 있어요."),

        // 역사
        ce(.middle, "선사 문화와 고대 국가의 형성", ["고조선의 성립과 발전", "단군왕검", "8조법"], "고조선은 청동기 문화를 바탕으로 성립한 우리 역사 최초의 국가로, 『삼국유사』에는 단군왕검이 건국했다고 기록되어 있어요. 고조선은 8조법을 만들어 사회 질서를 유지했는데, 지금은 3개 조항만 전해져요. 기원전 108년 한의 공격으로 왕검성이 함락되면서 멸망했어요.\n예: 8조법의 '사람을 죽인 자는 사형에 처한다'는 조항으로 생명을 중시했음을 알 수 있어요."),
        ce(.middle, "선사 문화와 고대 국가의 형성", ["여러 나라의 성장", "부여", "옥저와 동예", "삼한"], "고조선 멸망 전후로 만주와 한반도 각지에서 부여, 고구려, 옥저, 동예, 삼한 같은 여러 나라가 성장했어요. 제천 행사로 부여에는 영고, 동예에는 무천, 고구려에는 동맹이 있었고, 삼한은 5월과 10월에 계절제를 지냈어요. 옥저에는 민며느리제, 동예에는 책화라는 풍습이 있었어요.\n예: 삼한에서는 제사장인 천군이 신성 지역인 소도를 다스렸어요."),
        ce(.middle, "남북국 시대의 전개", ["통일 신라의 발전", "신문왕", "9주 5소경"], "삼국 통일 후 신라는 신문왕 때 김흠돌의 난을 진압하고, 관료전을 지급하는 대신 녹읍을 폐지해 왕권을 강화했어요. 지방은 9주 5소경으로 정비하고, 국학을 세워 유학을 가르쳤어요.\n예: 경주의 불국사와 석굴암은 통일 신라 불교문화를 대표해요."),
        ce(.middle, "남북국 시대의 전개", ["발해", "대조영", "해동성국"], "698년 고구려 장군 출신 대조영이 고구려 유민과 말갈인을 이끌고 동모산에서 발해를 세웠어요. 발해는 고구려를 계승했다고 밝혔고, 선왕 때 전성기를 맞아 '바다 동쪽의 번성한 나라'라는 뜻의 해동성국으로 불렸어요. 926년 거란의 침입으로 멸망했어요.\n예: 발해 문왕은 일본에 보낸 국서에서 스스로를 '고려(고구려) 국왕'이라고 칭했어요."),
        ce(.middle, "남북국 시대의 전개", ["신라 말의 혼란과 후삼국", "호족", "후백제와 후고구려"], "신라 말에는 진골 귀족들의 왕위 다툼으로 정치가 혼란해지고, 지방에서는 호족이 성장했어요. 견훤이 900년 후백제를, 궁예가 901년 후고구려를 세우면서 후삼국 시대가 시작됐어요.\n예: 6두품 출신 최치원은 진성 여왕에게 개혁안을 올렸지만 받아들여지지 않았어요."),
        ce(.middle, "남북국 시대의 전개", ["장보고와 해상 무역", "청해진", "신라방"], "통일 신라는 당, 일본과 활발히 교류했어요. 9세기 장보고는 완도에 청해진을 설치해 해적을 소탕하고 당, 신라, 일본을 잇는 해상 무역을 주도했어요. 당의 산둥반도 등에는 신라인의 마을인 신라방이 생겼어요.\n예: 장보고는 산둥반도에 법화원이라는 절을 세웠어요."),
        ce(.middle, "고려의 성립과 변천", ["고려의 건국과 후삼국 통일", "왕건", "태조 왕건"], "918년 왕건은 궁예를 몰아내고 고려를 세웠어요. 고려는 935년 신라의 항복을 받고, 936년 후백제를 무너뜨려 후삼국을 통일했어요. 태조 왕건은 호족을 포섭하는 정책과 북진 정책을 펼쳤어요.\n예: 태조는 지방 호족의 딸과 혼인하고 왕씨 성을 내려 주는 방법으로 호족을 포섭했어요."),
        ce(.middle, "고려의 성립과 변천", ["고려의 통치 체제 정비", "광종의 개혁", "노비안검법"], "광종은 노비안검법을 실시하여 억울하게 노비가 된 사람을 풀어 주고, 과거제를 처음 실시해 왕권을 강화했어요. 성종은 최승로의 시무 28조를 받아들여 유교 정치 이념을 바탕으로 중앙과 지방의 통치 제도를 정비했어요.\n예: 고려의 과거제는 958년 쌍기의 건의로 처음 실시됐어요."),
        ce(.middle, "고려의 성립과 변천", ["거란과 여진의 침입", "서희의 외교 담판", "귀주 대첩", "별무반"], "10세기 말부터 거란이 세 차례 고려를 침입했어요. 1차 침입 때 서희는 외교 담판으로 강동 6주를 얻었고, 3차 침입 때 강감찬은 귀주에서 거란군을 크게 물리쳤어요(1019년). 12세기 초에는 윤관이 별무반을 이끌고 여진을 정벌해 동북 9성을 쌓았어요.\n예: 거란의 침입 이후 고려는 개경에 나성을, 북쪽 국경에 천리장성을 쌓았어요."),
        ce(.middle, "고려의 성립과 변천", ["몽골의 침입과 원 간섭기", "삼별초", "강화도 천도"], "13세기 몽골이 침입하자 고려 무신 정권은 강화도로 도읍을 옮겨 항쟁했고, 백성들도 처인성 전투 등에서 맞서 싸웠어요. 고려가 몽골과 강화를 맺고 개경으로 돌아가자 삼별초는 이에 반대해 진도와 제주도로 옮겨 가며 항쟁했어요. 이후 고려는 오랫동안 원의 간섭을 받았어요.\n예: 팔만대장경은 몽골의 침입을 부처의 힘으로 물리치고자 만든 것이에요."),
        ce(.middle, "고려의 성립과 변천", ["공민왕의 개혁", "반원 자주 정책"], "14세기 중반 원이 약해지자 공민왕은 기철 등 친원 세력을 제거하고, 쌍성총관부를 공격해 철령 이북의 땅을 되찾는 반원 자주 정책을 펼쳤어요. 또 신돈을 등용해 전민변정도감을 설치하고 권문세족이 빼앗은 토지와 노비를 되돌려 주려 했어요.\n예: 공민왕은 몽골식 머리 모양인 변발을 금지했어요."),
        ce(.middle, "조선의 성립과 발전", ["조선의 건국", "이성계", "위화도 회군"], "이성계는 1388년 위화도 회군으로 권력을 잡은 뒤 신진 사대부와 함께 개혁을 추진하고, 1392년 조선을 건국했어요. 조선은 도읍을 한양으로 옮기고, 성리학을 통치 이념으로 삼았어요.\n예: 정도전은 『조선경국전』을 지어 조선 통치 체제의 기틀을 마련했어요."),
        ce(.middle, "조선의 성립과 발전", ["조선의 통치 체제", "경국대전", "의정부와 6조"], "조선은 성종 때 완성된 『경국대전』을 바탕으로 나라를 다스렸어요. 중앙에는 의정부와 6조를 두어 나랏일을 나누어 맡기고, 사헌부·사간원·홍문관의 삼사가 권력의 독점과 부정을 견제했어요. 지방은 8도로 나누고 수령을 파견했어요.\n예: 6조는 이조, 호조, 예조, 병조, 형조, 공조예요."),
        ce(.middle, "조선의 성립과 발전", ["세종의 업적", "집현전", "4군 6진"], "세종은 집현전을 설치해 학문을 연구하게 하고, 1443년 훈민정음을 창제하여 1446년에 반포했어요. 측우기, 자격루, 앙부일구 같은 과학 기구를 만들고, 『농사직설』을 펴냈으며, 4군 6진을 개척해 영토를 넓혔어요.\n예: 훈민정음은 '백성을 가르치는 바른 소리'라는 뜻이에요."),
        ce(.middle, "조선의 성립과 발전", ["사림의 성장과 사화", "사화", "붕당"], "성종 때부터 사림이 중앙 정계에 진출해 훈구 세력을 비판하자, 갈등이 커져 여러 차례 사림이 큰 피해를 입는 사화가 일어났어요. 사림은 서원과 향약을 바탕으로 세력을 키워 선조 때 정권을 잡았고, 이후 학문적·정치적 입장에 따라 동인과 서인 등의 붕당으로 나뉘었어요.\n예: 무오사화, 갑자사화, 기묘사화, 을사사화를 4대 사화라고 해요."),
        ce(.middle, "조선의 성립과 발전", ["왜란과 호란", "임진왜란과 병자호란"], "1592년 일본이 조선을 침략해 임진왜란이 일어났어요. 이순신이 이끄는 수군과 의병, 명의 지원군이 활약해 일본군을 물리쳤어요. 이후 1636년 청이 침입한 병자호란 때 인조는 남한산성에서 항전했지만 결국 삼전도에서 항복했어요.\n예: 이순신은 한산도 대첩에서 학익진 전법으로 일본 수군을 크게 물리쳤어요."),
        ce(.middle, "조선 사회의 변동", ["영조와 정조의 탕평 정치", "탕평 정치", "균역법", "규장각"], "영조와 정조는 붕당 간의 대립을 줄이고 왕권을 강화하기 위해 탕평 정치를 펼쳤어요. 영조는 균역법을 실시해 군역 부담을 줄였고, 정조는 규장각을 설치하고 수원 화성을 건설했어요.\n예: 균역법은 백성이 내던 군포를 2필에서 1필로 줄인 제도예요."),
        ce(.middle, "조선 사회의 변동", ["조선 후기의 경제 변화", "모내기법", "상품 작물", "상평통보"], "조선 후기에는 모내기법이 전국으로 퍼지면서 노동력은 줄고 생산량은 늘어 넓은 땅을 경작하는 광작이 유행했고, 인삼·담배 같은 상품 작물을 재배했어요. 공인과 사상 같은 상인이 성장하고 장시가 늘어났으며, 상평통보가 전국적으로 유통되었어요.\n예: 대동법 실시 이후 관청에 필요한 물품을 사서 납품하는 공인이 등장했어요."),
        ce(.middle, "조선 사회의 변동", ["서민 문화의 발달", "한글 소설", "판소리", "풍속화"], "조선 후기에는 서민의 경제력과 의식이 성장하면서 서민 문화가 발달했어요. 『홍길동전』, 『춘향전』 같은 한글 소설과 사설시조가 유행했고, 판소리와 탈춤이 인기를 얻었어요. 김홍도와 신윤복은 서민과 양반의 생활 모습을 풍속화로 그렸어요.\n예: 김홍도의 「씨름」, 신윤복의 「단오풍정」은 대표적인 풍속화예요."),
        ce(.middle, "조선 사회의 변동", ["세도 정치와 농민 봉기", "홍경래의 난", "임술 농민 봉기"], "19세기 순조, 헌종, 철종 때 소수의 외척 가문이 권력을 독점한 세도 정치가 이어지면서 삼정(전정, 군정, 환곡)이 문란해졌어요. 이에 반발해 1811년 홍경래의 난, 1862년 진주에서 시작된 임술 농민 봉기가 일어났어요.\n예: 안동 김씨와 풍양 조씨가 대표적인 세도 가문이에요.")
    ]
}
